//! Checks `dumps` and `float_repr` against CPython's `json.dumps` and
//! `float.__repr__`.
//!
//! `data/json_vectors.txt` is generated by
//! `crates/pyjson/scripts/gen_json_vectors.py`; its header documents the
//! line format. Every line is checked, and every mismatch is reported at
//! once. Setting `KASSIBER_JSON_VECTORS` to another generated file (a stress
//! run) checks that file as well.

use std::collections::BTreeMap;

use kassiber_pyjson::{dumps, float_repr, BigInt, Decimal, Indent, Key, Options, PyStr, Value};

const VECTORS: &str = include_str!("data/json_vectors.txt");

/// Fewest float cases, so a truncated file cannot pass.
const MIN_FLOATS: usize = 10_000;

/// Fewest cases for each combination of the varied options.
const MIN_PER_COMBINATION: usize = 40;

/// Fewest cases for each option set kassiber/ passes (README.md), which the
/// generator also feeds Kassiber-shaped payloads.
const MIN_PER_SURVEYED: usize = 60;

/// The option sets the survey found, in the vectors' spelling.
const SURVEYED: [&str; 14] = [
    "-",
    "sort",
    "compact",
    "sort compact",
    "ascii=0 compact",
    "ascii=0 sort compact",
    "nan=0 sort compact",
    "ascii=0 nan=0 sort compact",
    "sort compact str",
    "ascii=0 sort compact str",
    "sort str",
    "str",
    "indent=2",
    "sort indent=2",
];

/// Undoes the text escapes: `\\` and `\u{<hex>}`.
fn unescape(text: &str) -> Result<Vec<u32>, String> {
    let mut points = Vec::new();
    let mut rest = text;
    while let Some(c) = rest.chars().next() {
        if c != '\\' {
            points.push(u32::from(c));
            rest = &rest[c.len_utf8()..];
        } else if let Some(after) = rest.strip_prefix("\\\\") {
            points.push(u32::from('\\'));
            rest = after;
        } else if let Some(after) = rest.strip_prefix("\\u{") {
            let end = after
                .find('}')
                .ok_or_else(|| format!("unterminated escape in {text:?}"))?;
            let point = u32::from_str_radix(&after[..end], 16)
                .map_err(|_| format!("bad escape in {text:?}"))?;
            points.push(point);
            rest = &after[end + 1..];
        } else {
            return Err(format!("bad escape in {text:?}"));
        }
    }
    Ok(points)
}

fn unescape_string(text: &str) -> Result<String, String> {
    unescape(text)?
        .into_iter()
        .map(|point| char::from_u32(point).ok_or_else(|| format!("surrogate in {text:?}")))
        .collect()
}

fn py_str(text: &str) -> Result<PyStr, String> {
    PyStr::from_code_points(unescape(text)?).map_err(|e| e.to_string())
}

fn float(bits: &str) -> Result<f64, String> {
    u64::from_str_radix(bits, 16)
        .map(f64::from_bits)
        .map_err(|_| format!("bad float bits {bits:?}"))
}

fn options(text: &str) -> Result<Options, String> {
    let mut options = Options::new();
    if text == "-" {
        return Ok(options);
    }
    let mut item = None;
    let mut key = None;
    for flag in text.split(' ') {
        match flag {
            "ascii=0" => options = options.ensure_ascii(false),
            "nan=0" => options = options.allow_nan(false),
            "sort" => options = options.sort_keys(true),
            "compact" => options = options.compact(),
            "str" => options = options.default_str(true),
            _ => {
                if let Some(text) = flag.strip_prefix("indent=s") {
                    options = options.indent(Indent::Text(unescape_string(text)?));
                } else if let Some(n) = flag.strip_prefix("indent=") {
                    let n = n
                        .parse::<usize>()
                        .map_err(|_| format!("bad indent {flag:?}"))?;
                    options = options.indent(n);
                } else if let Some(text) = flag.strip_prefix("item=s") {
                    item = Some(unescape_string(text)?);
                } else if let Some(text) = flag.strip_prefix("key=s") {
                    key = Some(unescape_string(text)?);
                } else {
                    return Err(format!("unknown option {flag:?}"));
                }
            }
        }
    }
    match (item, key) {
        (Some(item), Some(key)) => Ok(options.separators(&item, &key)),
        (None, None) => Ok(options),
        _ => Err("item= and key= come together".to_string()),
    }
}

fn scalar_key(token: &str) -> Result<Key, String> {
    Ok(match token.split_at(1) {
        ("N", "") => Key::Null,
        ("T", "") => Key::Bool(true),
        ("F", "") => Key::Bool(false),
        ("i", digits) => Key::Int(
            digits
                .parse::<BigInt>()
                .map_err(|_| format!("bad int {token:?}"))?,
        ),
        ("f", bits) => Key::Float(float(bits)?),
        ("s", text) => Key::Str(py_str(text)?),
        _ => return Err(format!("bad key token {token:?}")),
    })
}

/// The value that starts with `token`, reading the rest from `tokens`.
fn value<'a>(token: &str, tokens: &mut impl Iterator<Item = &'a str>) -> Result<Value, String> {
    Ok(match token {
        "[" => {
            let mut items = Vec::new();
            loop {
                match tokens.next().ok_or("unterminated list")? {
                    "]" => break,
                    token => items.push(value(token, tokens)?),
                }
            }
            Value::List(items)
        }
        "{" => {
            let mut items = Vec::new();
            loop {
                match tokens.next().ok_or("unterminated dict")? {
                    "}" => break,
                    token => {
                        let key = scalar_key(token)?;
                        let first = tokens.next().ok_or("dict ends after a key")?;
                        items.push((key, value(first, tokens)?));
                    }
                }
            }
            Value::Dict(items)
        }
        _ => match token.split_at(1) {
            ("d", text) => Value::Decimal(
                Decimal::from_canonical(text).map_err(|e| format!("bad decimal {token:?}: {e}"))?,
            ),
            _ => match scalar_key(token)? {
                Key::Null => Value::Null,
                Key::Bool(b) => Value::Bool(b),
                Key::Int(n) => Value::Int(n),
                Key::Float(x) => Value::Float(x),
                Key::Str(s) => Value::Str(s),
            },
        },
    })
}

fn input(text: &str) -> Result<Value, String> {
    let mut tokens = text.split(' ');
    let first = tokens.next().ok_or("empty input")?;
    let parsed = value(first, &mut tokens)?;
    match tokens.next() {
        None => Ok(parsed),
        Some(extra) => Err(format!("trailing token {extra:?}")),
    }
}

fn check(fields: &[&str]) -> Result<(), String> {
    match fields {
        ["float", bits, expected] => {
            let x = float(bits)?;
            let actual = float_repr(x);
            if actual != *expected {
                return Err(format!("float_repr gave {actual:?}"));
            }
            // As a JSON value the float writes its repr, or JSON's spelling
            // of the specials.
            let json = dumps(&Value::Float(x), &Options::new()).map_err(|e| e.to_string())?;
            let want = match *expected {
                "nan" => "NaN",
                "inf" => "Infinity",
                "-inf" => "-Infinity",
                other => other,
            };
            if json != want {
                return Err(format!("dumps gave {json:?}"));
            }
            Ok(())
        }
        ["dumps", opts, text, expected] => {
            let options = options(opts)?;
            let value = input(text)?;
            let actual = match dumps(&value, &options) {
                Ok(out) => out,
                Err(error) => format!("!{error:?}"),
            };
            let expected = if expected.starts_with('!') {
                (*expected).to_string()
            } else {
                unescape_string(expected)?
            };
            if actual != expected {
                return Err(format!("dumps gave {actual:?}\n    expected {expected:?}"));
            }
            Ok(())
        }
        _ => Err("unrecognized line".to_string()),
    }
}

/// The 64 combinations of the varied options, spelled as the vectors do.
fn combinations() -> Vec<String> {
    let mut all = Vec::new();
    for bits in 0..64u32 {
        let flags: Vec<&str> = [
            (bits & 1 != 0, "ascii=0"),
            (bits & 2 != 0, "nan=0"),
            (bits & 4 != 0, "sort"),
            (bits & 8 != 0, "indent=2"),
            (bits & 16 != 0, "compact"),
            (bits & 32 != 0, "str"),
        ]
        .into_iter()
        .filter_map(|(on, flag)| on.then_some(flag))
        .collect();
        all.push(if flags.is_empty() {
            "-".to_string()
        } else {
            flags.join(" ")
        });
    }
    all
}

/// Checks every case in `text`, appending failures to `mismatches`. With
/// `require_coverage`, also fails when a kind of case has too few vectors.
fn check_file(
    name: &str,
    text: &str,
    require_coverage: bool,
    mismatches: &mut Vec<String>,
) -> usize {
    let mut floats = 0;
    let mut per_options: BTreeMap<&str, usize> = BTreeMap::new();
    let mut total = 0;
    for (index, line) in text.lines().enumerate() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        total += 1;
        let fields: Vec<&str> = line.split('\t').collect();
        match fields.first() {
            Some(&"float") => floats += 1,
            Some(&"dumps") if fields.len() > 1 => *per_options.entry(fields[1]).or_default() += 1,
            _ => {}
        }
        if let Err(problem) = check(&fields) {
            let shown: String = line.chars().take(300).collect();
            mismatches.push(format!("{name}:{}: {shown}\n    {problem}", index + 1));
        }
    }
    if require_coverage {
        if floats < MIN_FLOATS {
            mismatches.push(format!(
                "{name}: only {floats} float cases; expected at least {MIN_FLOATS}"
            ));
        }
        for options in combinations() {
            let n = per_options.get(options.as_str()).copied().unwrap_or(0);
            if n < MIN_PER_COMBINATION {
                mismatches.push(format!(
                    "{name}: only {n} cases for options {options:?}; expected at least {MIN_PER_COMBINATION}"
                ));
            }
        }
        for options in SURVEYED {
            let n = per_options.get(options).copied().unwrap_or(0);
            if n < MIN_PER_SURVEYED {
                mismatches.push(format!(
                    "{name}: only {n} cases for surveyed options {options:?}; expected at least {MIN_PER_SURVEYED}"
                ));
            }
        }
    }
    total
}

#[test]
fn json_vectors_match_cpython() {
    let mut mismatches = Vec::new();
    let mut total = check_file("json_vectors.txt", VECTORS, true, &mut mismatches);
    if let Some(path) = std::env::var_os("KASSIBER_JSON_VECTORS") {
        let extra = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.to_string_lossy()));
        total += check_file(&path.to_string_lossy(), &extra, false, &mut mismatches);
    }
    assert!(
        mismatches.is_empty(),
        "{} of {total} json vectors failed:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
